import{_ as o,C as s,o as n,c as i,a2 as t,E as r}from"./chunks/framework.9yf7n3zg.js";const d="/guide/media/tags-overview.webp",h="/guide/media/tags-column.webp",f=JSON.parse('{"title":"Tags","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tags.md","filePath":"guide/tags.md","lastUpdated":1792171429000}'),l={name:"guide/tags.md"};function c(g,e,p,u,m,w){const a=s("Clip");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h1><p>The Tags view lists every tag in your writing home, from your notes and from Leathercase&#39;s, and lets you describe, colour, rename, merge and delete them. It sits beside the Library, the Desk and the Writer, because tags belong to the home, not to one story. This page covers what counts as a tag, how the view is laid out, what each change writes, and how a <code>#tag</code> typed into a card becomes a chip.</p><p>Leathercase writes tags only into its own files: the Writer Board&#39;s cards, the notes it made, and <code>suite/Tags.md</code>. Your notes keep their tags as written.</p><p><img src="'+d+'" alt="The Tags view on the sample home: the tree of tags, the notes carrying #sea, and the side column with its colour and description" width="1130" height="700" loading="lazy"></p><h2 id="open-the-view" tabindex="-1">Open the view <a class="header-anchor" href="#open-the-view" aria-label="Permalink to &quot;Open the view&quot;">​</a></h2><p>Click <strong>Tags</strong> under <strong>Home</strong> in the sidebar, or press <code>Ctrl+8</code> (Cmd+8 on macOS). Picking a tag in the find field also opens the view with that tag selected.</p><p>The line at the top counts what is there: <strong>9 tags · 12 notes tagged · 3 described</strong>.</p><h2 id="what-counts-as-a-tag" tabindex="-1">What counts as a tag <a class="header-anchor" href="#what-counts-as-a-tag" aria-label="Permalink to &quot;What counts as a tag&quot;">​</a></h2><p>A tag is what Obsidian and most markdown tools read as one:</p><ul><li><strong>In front matter</strong>: <code>tags: [sea, guilt]</code> or <code>tag: sea</code>, with or without <code>#</code>.</li><li><strong>In the text</strong>: <code>#sea</code>, a <code>#</code> with no space after it. <code># Heading</code> stays a heading. A tag cannot be all digits, and a <code>#</code> inside code, a link, a web address or a comment is not a tag.</li><li><strong>Nested with a slash</strong>: <code>#sea/charts</code> sits under <code>#sea</code>.</li></ul><p>Every markdown note in the home is read for tags, whether it belongs to a story or not. Case does not matter: <code>#Sea</code> and <code>#sea</code> are one tag. Tags a connected agent proposed show here only once you accept them in the <a href="/guide/guide/inbox">inbox</a>.</p><h2 id="the-layout" tabindex="-1">The layout <a class="header-anchor" href="#the-layout" aria-label="Permalink to &quot;The layout&quot;">​</a></h2><p>The view has three parts.</p><p><strong>The tree</strong>, on the left, lists every tag alphabetically. A nested tag is indented under its parent and shows only its last part, so <code>#sea/charts</code> reads as <code>charts</code> under <code>sea</code>. Each row has the tag&#39;s colour dot and how many notes carry it, counting the tags below it. Two groups come apart at the foot:</p><ul><li><strong>the board&#39;s lists · #writer</strong>: the tags that put a note in a list of the Writer Board, such as <code>#writer/theme</code>.</li><li><strong>Kinds of your own</strong>: the kinds a story declared for itself (see <a href="#kinds-of-your-own">Kinds of your own</a> below).</li></ul><p><strong>The notes</strong>, in the middle, list the notes carrying the selected tag. Before you pick one it says <strong>Pick a tag to see the notes that carry it.</strong> For a tag, it shows the tag as a chip, its description, and each note with:</p><ul><li>the note&#39;s name, which you click to open it;</li><li>its path;</li><li><strong>Leathercase&#39;s</strong> or <strong>yours</strong>;</li><li><strong>as #place</strong>, when the note carries an older name of the tag (see renaming, below);</li><li><strong>take off</strong>, on Leathercase&#39;s notes, which takes the tag off that note.</li></ul><p>When no note carries the tag itself but tags below it do, it says <strong>No note carries this tag itself; its tags below it do.</strong> A tag described in <code>Tags.md</code> that no note carries says <strong>No note carries it; the tags note still describes it.</strong> When the count includes nested tags, a line under the list says so, such as <strong>5 notes counting the tags below it</strong>.</p><p><strong>The side column</strong>, on the right, says what Leathercase keeps about the selected tag, with the changes you can make. With nothing selected, it explains the view and names the file it keeps things in, <code>suite/Tags.md</code>.</p><p>When no note in the home carries a tag yet, the view says <strong>No note of this library carries a tag yet. A tag is a word in a note&#39;s tags, or #inline; put one on a card on the writer board and it shows here.</strong></p><h2 id="open-a-note" tabindex="-1">Open a note <a class="header-anchor" href="#open-a-note" aria-label="Permalink to &quot;Open a note&quot;">​</a></h2><p>Click a note&#39;s name in the middle pane, or select a tag and press <code>Enter</code> to open its first note:</p><ul><li>A card the Writer Board made opens on the board, selected.</li><li>Any other note opens in the program you write in.</li></ul><h2 id="describe-a-tag" tabindex="-1">Describe a tag <a class="header-anchor" href="#describe-a-tag" aria-label="Permalink to &quot;Describe a tag&quot;">​</a></h2><p>Select a tag and the column shows <strong>#sea</strong>, with <strong>close</strong>, and a count: <strong>4 notes · 3 Leathercase&#39;s · 1 yours</strong>. When tags nested under it (<code>#sea/storm</code> under <code>#sea</code>) carry notes too, the count goes on with the total that includes them, such as <strong>· 6 counting the tags below</strong>, and the list of notes ends with the same total. Below it:</p><ul><li><strong>Colour</strong>: click the swatch to give the tag a colour. <strong>none</strong> clears it. The colour shows on the tag&#39;s dot here and on its chips on every card of the Writer Board and the <a href="/guide/guide/beat-board">Beat board</a>.</li><li><strong>What the tag is for, in a line.</strong>: a description, saved when you leave the field or the view.</li><li><strong>also read as</strong>, listing the older names this tag has taken over.</li></ul><p><img src="'+h+'" alt="The side column for #sea: the colour, the description, and Rename or merge and Delete below" width="375" height="650" loading="lazy"></p><h2 id="rename-or-merge-a-tag" tabindex="-1">Rename or merge a tag <a class="header-anchor" href="#rename-or-merge-a-tag" aria-label="Permalink to &quot;Rename or merge a tag&quot;">​</a></h2><p>Under <strong>Rename or merge</strong>, type a new name in <strong>a new name, or a tag to merge into</strong>. The field offers the tags the home already has. The button reads <strong>Rename</strong> for a new name and <strong>Merge</strong> when the name is a tag that exists.</p><p>What it changes:</p><ul><li><strong>Leathercase&#39;s notes</strong> are rewritten: every card and every note Leathercase made that carries the tag now carries the new name. Tags nested below it follow, so renaming <code>place</code> to <code>setting</code> makes <code>place/coast</code> into <code>setting/coast</code>.</li><li><strong>Your notes</strong> keep the old name as written. Leathercase records the old name as another name of the new tag in <code>Tags.md</code>, so your note shows under the new tag with <strong>as #place</strong> beside it.</li></ul><p>After the change nothing is selected; pick the new name in the tree to see its notes.</p><p>The help line under the field says how many notes of each kind the change touches, such as <strong>rewrites Leathercase&#39;s 2 notes and the tags below it; your 1 note keeps #place, read as the new name</strong>. After a rename, the new tag&#39;s help line names the old tag your notes still carry: with <code>sea</code> renamed to <code>ocean</code>, picking <code>#ocean</code> reads <strong>…; your 1 note keeps #sea, read as the new name</strong>.</p>',33)),r(a,{name:"tags-rename",caption:"Renaming sea to ocean: Leathercase's cards are rewritten, the writer's note keeps #sea and shows under #ocean as #sea"}),e[1]||(e[1]=t(`<h2 id="delete-a-tag" tabindex="-1">Delete a tag <a class="header-anchor" href="#delete-a-tag" aria-label="Permalink to &quot;Delete a tag&quot;">​</a></h2><p>Under <strong>Delete</strong>, <strong>Delete the tag</strong> takes the tag off Leathercase&#39;s notes and out of <code>Tags.md</code>. Your notes keep it, so it may stay in the tree with only your notes under it. The hint beside the section says how many of Leathercase&#39;s notes it would rewrite, or <strong>nothing to rewrite</strong>.</p><h2 id="the-board-s-lists" tabindex="-1">The board&#39;s lists <a class="header-anchor" href="#the-board-s-lists" aria-label="Permalink to &quot;The board&#39;s lists&quot;">​</a></h2><p>A tag under <code>writer/</code> puts a note in a list of the Writer Board. Selecting one shows only an explanation: <strong>This tag puts a note in a list of the writer board. Move a card, or rename or remove the list, on the board.</strong> Change those on the <a href="/guide/guide/writer-board#change-the-lists">Writer Board</a>.</p><h2 id="make-a-tag" tabindex="-1">Make a tag <a class="header-anchor" href="#make-a-tag" aria-label="Permalink to &quot;Make a tag&quot;">​</a></h2><p>Type <code>tag: grief</code> in the find field and press Enter. On the Writer Board with one of the board&#39;s cards selected, the tag goes on that card. Anywhere else, the tag is entered in <code>suite/Tags.md</code> and the Tags view opens with it selected, ready to describe. See <a href="/guide/guide/find#make-something-with-a-word-and-a-colon">Find, open and make</a>.</p><h2 id="a-tag-typed-into-a-card-becomes-a-chip" tabindex="-1">A #tag typed into a card becomes a chip <a class="header-anchor" href="#a-tag-typed-into-a-card-becomes-a-chip" aria-label="Permalink to &quot;A #tag typed into a card becomes a chip&quot;">​</a></h2><p>In Leathercase&#39;s own notes, a <code>#tag</code> you type is taken out of the text and put in the note&#39;s tags, where the views show it as a chip. This is how it works on the <a href="/guide/guide/writer-board#make-a-card">Writer Board</a> and the <a href="/guide/guide/beat-board">Beat board</a>:</p><ul><li>Make a card titled <code>Lamp #mystery</code> and you get the card Lamp, tagged mystery.</li><li>Write <code>Kept lit. #place/coast</code> in a card&#39;s text and the text reads Kept lit., with the chip <code>#place/coast</code>.</li><li>A line left with nothing but its tags goes with them.</li></ul><p>Your own notes are never changed this way. In them, a <code>#tag</code> stays in the text where you wrote it, and Leathercase only reads it.</p><h2 id="kinds-of-your-own" tabindex="-1">Kinds of your own <a class="header-anchor" href="#kinds-of-your-own" aria-label="Permalink to &quot;Kinds of your own&quot;">​</a></h2><p>When a story has kinds of its own, such as symbols or ships, they are listed in the tree under <strong>Kinds of your own</strong>, one row per kind and story: <strong>Symbol · The Lamp at Ferrol</strong>, with how many notes it has.</p><p>Pick a row and the middle pane lists the notes of that kind, each with the scenes it is found in (<strong>in 3 scenes</strong>) and <strong>Open</strong>. A kind of names is found in the prose by its names and other names, as a character is. A symbol is also found by its images:</p><ol><li>Pick the symbol&#39;s row, then the note.</li><li>In the column, list under <strong>Images, one per line</strong> the words the prose uses for it besides its name: for the lamp, <code>the light</code>, <code>the beam</code>.</li><li>Click <strong>Keep images</strong>.</li></ol><p>The images are kept in a note Leathercase keeps beside yours, <code>suite/Kinds/Symbol/The lamp.md</code> in the story&#39;s folder. Your note is never changed. An <code>## Images</code> section you write in your own note is read too, and its images join the ones kept here (see <a href="/guide/reference/formats#markdown">Files Leathercase reads</a>). The kind is declared when Leathercase asks what notes of an unknown <code>type:</code> are (for instance in <a href="/guide/guide/how-a-story-is-read">How a story is read</a>); the <a href="/guide/guide/graph">Graph</a> then draws its notes as names, with a diamond, counted among the kinds of your own. A symbol&#39;s note can also say what it stands for, under a <code>## Stands for</code> heading, and the Graph draws that as a tie.</p><h2 id="what-tags-md-holds" tabindex="-1">What Tags.md holds <a class="header-anchor" href="#what-tags-md-holds" aria-label="Permalink to &quot;What Tags.md holds&quot;">​</a></h2><p><code>suite/Tags.md</code>, at the root of the home, is a small markdown file with one section per tag you said something about:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Tags</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## sea</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> colour: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`#5fa8a0\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> aliases: ocean</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The sea as a character: it owes nothing and forgives nothing.</span></span></code></pre></div><p>The heading is the tag, <code>colour:</code> its colour, <code>aliases:</code> its older names, and the rest of the section its description. You can edit it by hand; Leathercase reads it back. It is not read as a note that carries tags.</p><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Walk the tags</td></tr><tr><td><code>Enter</code></td><td>Open the first note of the selected tag</td></tr><tr><td><code>Esc</code></td><td>Deselect</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/writer-board">The Writer Board</a></li><li><a href="/guide/guide/find">Find, open and make</a></li><li><a href="/guide/guide/beat-board">Beat board</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li></ul>`,23))])}const b=o(l,[["render",c]]);export{f as __pageData,b as default};
